head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05911.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "";
scwin.trsIdx; // insert, update 구분

scwin.isFirstLoad = false;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    if (scwin.fr_bz_procs_no != "") {
        var url = "/Listing.do?method=searchChgList" + "&DIV_IDX=" + DIV_IDX_CHGLIST_PRC + "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_Isu.DataID = encodeURI(url);
        dts_Isu.reset();
    }
};
scwin.fn_new_onload = function() {
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CHGLIST_PRC_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CHGLIST_PRC_INOUT";
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.reset();
};
scwin.fn_GetParIsu = function(arrPar, param_dts) {
    arrPar[0] = scwin.Isur_cd;
    arrPar[1] = scwin.gubun;
    $c.stf.CopyDataSet(dts_Isu, param_dts);
};
scwin.fn_SetParIsu = function(param_dts) {
    $c.stf.CopyDataSet(param_dts, dts_Isu);
    //alert(dts_Isu.text + "\n\n" + param_dts.text);

};
scwin.fn_CheckForm = function() {
    if (!$c.lc.checkDdTm("DD", edt_MktactEnforceDd, "변경상장", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_ChgRsnContn, "변경사유")) return false;
    if (!$c.stf.checkMaxLength(txb_ChgRsnContn, 2000, "변경사유")) return false;
    if (dts_Isu.getTotalRow() == 0) {
        $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        if (dts_Isu.getCellData(i, "AFCHG_EXER_PRC") == "" || dts_Isu.getCellData(i, "AFCHG_EXER_PRC") == 0 ||
            dts_Isu.getCellData(i, "AFCHG_CONV_RTO") == "" || dts_Isu.getCellData(i, "AFCHG_CONV_RTO") == 0) {
            $c.win.alert($c.stf.getMessageParam("MSG-0019", ""));
            return false;
        }
    }
    return true;
};
scwin.fn_save_trs = function() {
    grd_isu.redraw = false;
    for (var i = 1; i <= dts_Isu.getTotalRow(); i++) {
        dts_Isu.setCellData(i, "ISUR_CD", scwin.Isur_cd);
        dts_Isu.setCellData(i, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
        dts_Isu.setCellData(i, "CHG_DD", edt_MktactEnforceDd.getValue());
        dts_Isu.setCellData(i, "CHG_RSN_CONTN", txb_ChgRsnContn.getValue());
    }
    grd_isu.redraw = true;
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lc.fn_encodeNSession("/Listing.do?method=saveChgList&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Isu )";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=1" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_147 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_PRC;
    trs.Post();
};
scwin.fn_save = function() {
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess('I')) return;
        scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.fr_bz_procs_no.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.trsIdx = TRS_IDX_INSERT;
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lc.fn_isProcess('U')) return;
        scwin.fn_save_trs();
    }
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_save_trs();
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.trs_OnFail = function() {
    $c.lc.fn_alertMsg('F');
};
scwin.trs_OnSuccess = async function() {
    $c.lc.fn_alertMsg('S');
    if (buttonSet.status == "D") {
        // 삭제처리의 응답인 경우
        await $c.frame.CloseFrame();
    } else {
        scwin.fn_search();
    }
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.

        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값

    }

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    //buttonSet.setDsclInfo( btn_Dscl, fn_dscl );			// 안내문작성

    if (scwin.fr_bz_procs_no != "") {
        // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
        scwin.fn_search();
    } else {
        scwin.fn_new_onload(); // 신규작성시 호출

    }
    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_MktactEnforceDd_onclick = function() {
    popUpCalendar2(edt_MktactEnforceDd);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
        //	dts_Isu.AddRow();

    } else {
        if (dts_Isu.getTotalRow() > 0) {
            edt_MktactEnforceDd.setValue(dts_Isu.getCellData(1, "CHG_DD"));
            txb_ChgRsnContn.setValue(dts_Isu.getCellData(1, "CHG_RSN_CONTN"));
        }
        $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false);
    }
};
scwin.img_SetIsuCd_onclick = function() {
    fn_GetPar = fn_GetParIsu;
    fn_SetPar = fn_SetParIsu;
    $c.lc.fn_PopFindElwCode();
};
scwin.img_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts_Isu.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd_isu, "ELW 행사겨격/전환비율 변경", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.btn_exelUpload_onclick = function() {
    var res = window.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.");
    if (res) {

        //dts_Isu.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_Isu.Do("LoadExcelData", "'','Sheet1',2,0,2");
    }
};
